import org.junit.jupiter.params.provider.CsvSource;

class PageTextPrototypeScanTest {

	@Test
	void persistedUnicodeLabelsKeepWholeStringLowercaseSemantics() throws Exception {
		List<String> labels = List.of("Long Greek label ending in ΟΣ",
				"Long Turkish label İI with embedded \u0000 and 💡",
				"An unrelated supplementary character 😀 in a long label", "An ordinary long ASCII label");
		List<Query> queries = List.of(new Query("final_sigma", Operation.CONTAINS, "ος"),
				new Query("expansion", Operation.CONTAINS, "i\u0307i"),
				new Query("nul", Operation.CONTAINS, "\u0000 and 💡"));
		var dataset = new Dataset(labels, labels.stream().map(label -> label.toLowerCase(Locale.ROOT)).toList(),
				queries);
		for (Query query : queries) {
			try (var scan = new PageTextPrototypeScan(dataset, 1, 1, Variant.FOURGRAM4096, query)) {
				for (Pipeline pipeline : Pipeline.values()) {
					assertEquals(1, scan.scan(pipeline), query.name() + "/" + pipeline);
				}
			}
		}
	}

	@ParameterizedTest
	@CsvSource({
			"CATALOG,SHUFFLED,16,128,COMMON16,contains_rare",
			"CATALOG,SHUFFLED,16,128,GRAM4096,contains_rare",
			"CATALOG,SHUFFLED,16,128,FOURGRAM4096,contains_absent_word",
			"CATALOG,SHUFFLED,16,128,EQ_HASH1024,equals_hit",
			"CATALOG,SHUFFLED,16,128,PREFIX_GRAM1024,prefix_rare",
			"CATALOG,CLUSTERED,64,256,PREFIX_RANGE,prefix_rare",
			"UNICODE,SHUFFLED,16,128,FOURGRAM4096,contains_unicode",
			"UNICODE,SHUFFLED,16,128,ASCII128,contains_absent_emoji",
			"CATALOG,SHUFFLED,64,256,GRAM256,contains_common",
			"CATALOG,CLUSTERED,4096,4160,GRAM4096,contains_rare"
	})
	void actualPagesAndDictionaryAgreeWithExactEvaluation(Corpus corpus, Order order, int entries, int size,
			Variant variant, String queryName) throws Exception {
		var dataset = PageTextPrototypeWorkload.create(corpus, order, size);
		var query = dataset.query(queryName);
		long expected = dataset.normalized().stream().filter(query::matches).count();
		try (var scan = new PageTextPrototypeScan(dataset, entries, entries > 1024 ? 4 : 1, variant, query)) {
			for (Pipeline pipeline : Pipeline.values()) {
				assertEquals(expected, scan.scan(pipeline), pipeline.name());
				var counts = scan.lastCounts();
				assertTrue(counts.decodedIds() <= size);
				assertTrue(counts.materializations() >= expected);
				assertTrue(counts.materializations() <= counts.decodedIds());
				if (pipeline == Pipeline.NONE) {
					assertEquals(size, counts.materializations());
					assertEquals(scan.pages().pageCount(), counts.decodedPages());
				}
				if (pipeline == Pipeline.LITERAL_ONLY) {
					assertEquals(scan.pages().pageCount(), counts.decodedPages());
					assertEquals(size, counts.decodedIds());
					assertEquals(counts.decodedIds(), counts.literalProbes());
				}
				if (pipeline == Pipeline.NONE || pipeline == Pipeline.PAGE_ONLY) {
					assertEquals(0, counts.literalProbes());
				}
				if (pipeline == Pipeline.PAGE_AND_LITERAL && variant == Variant.EQ_HASH1024) {
					assertTrue(counts.decodedPages() < scan.pages().pageCount());
					assertEquals(expected, counts.materializations());
				}
			}
		}
	}
}
